<script setup lang="ts">
import {computed,ref,watch} from 'vue'
const props=defineProps<{state:any}>()
const emit=defineEmits(['navigate','graph','properties'])
type Resource={id:string;name:string;description:string;kind:string;raw:any}
const category=ref('objects'),query=ref(''),view=ref('cards'),selected=ref('')
const categories=[{id:'objects',name:'对象类型',en:'Object Types',page:'model'},{id:'links',name:'链接类型',en:'Link Types',page:'links'},{id:'actions',name:'行动类型',en:'Action Types',page:'actions'},{id:'interfaces',name:'接口',en:'Interfaces',page:'interfaces'},{id:'shared',name:'共享属性',en:'Shared Properties',page:'properties'},{id:'groups',name:'对象类型组',en:'Object Type Groups',page:''}]
const graph=computed<any[]>(()=>props.state?.ontology?.['@graph']||[])
const workflow=computed(()=>props.state?.workflow||{})
const idOf=(x:any)=>typeof x==='string'?x:x?.['@id']||x?.id||''
const title=(x:any)=>x?.['rdfs:label']||x?.displayName||x?.name||idOf(x)||'未命名'
const objects=computed(()=>graph.value.filter(x=>x['@type']==='owl:Class'))
const localProps=computed(()=>graph.value.filter(x=>x['@type']==='owl:DatatypeProperty'))
const links=computed(()=>graph.value.filter(x=>x['@type']==='owl:ObjectProperty'))
const reference=(id:string)=>graph.value.find(x=>idOf(x)===id)||objects.value.find(x=>idOf(x).split(':').pop()===id)
const name=(id:string)=>id?(reference(id)?title(reference(id)):id):'未配置'
const groupRows=computed(()=>Array.isArray(props.state?.ontology?.objectTypeGroups)?props.state.ontology.objectTypeGroups:graph.value.filter(x=>['mg:ObjectTypeGroup','ObjectTypeGroup'].includes(x['@type'])))
const resources=computed<Resource[]>(()=>{
 const sets={objects:objects.value,links:links.value,actions:workflow.value.actions||[],interfaces:workflow.value.interfaces||[],shared:graph.value.filter(x=>x['@type']==='mg:SharedProperty'),groups:groupRows.value}
 return Object.entries(sets).flatMap(([kind,rows])=>(rows as any[]).map(raw=>({id:idOf(raw),name:title(raw),description:raw['rdfs:comment']||raw.description||'',kind,raw})))
})
const rows=computed(()=>resources.value.filter(x=>x.kind===category.value&&[x.name,x.id,x.description,...(x.raw['mg:aliases']||[])].join(' ').toLowerCase().includes(query.value.trim().toLowerCase())))
watch(rows,items=>{if(!items.some(x=>x.id===selected.value))selected.value=items[0]?.id||''},{immediate:true})
const current=computed(()=>rows.value.find(x=>x.id===selected.value))
const info=computed(()=>categories.find(x=>x.id===category.value)!)
const objectProperties=computed(()=>localProps.value.filter(p=>idOf(p['rdfs:domain'])===selected.value))
const relatedLinks=computed(()=>links.value.filter(p=>[idOf(p['rdfs:domain']),idOf(p['rdfs:range'])].includes(selected.value)))
const sameType=(type:string)=>type===selected.value||type===selected.value.split(':').pop()
const relatedActions=computed(()=> (workflow.value.actions||[]).filter(a=>sameType(a.object_type)))
const sharedUsage=computed(()=>localProps.value.filter(p=>idOf(p['mg:sharedProperty'])===selected.value))
const resolveProperty=(p:any)=>reference(idOf(p['mg:sharedProperty']))||p
const dataType=(p:any)=>idOf(resolveProperty(p)?.['rdfs:range']).replace('xsd:','')||'未配置'
const cardinality=(n:any)=>({'one-to-one':'一对一','one-to-many':'一对多','many-to-one':'多对一','many-to-many':'多对多'}[n['mg:cardinality']]||'未配置')
const groupMembers=computed(()=>{const g=current.value?.raw;return Array.isArray(g?.objectTypeIds)?g.objectTypeIds:Array.isArray(g?.objectTypes)?g.objectTypes:[]})
function selectCategory(id:string){category.value=id;query.value=''}
function openResource(kind:string,id:string){category.value=kind;query.value='';selected.value=id}
</script>
<template>
<section class="discover">
 <header class="discover-heading"><div><span class="eyebrow">资源浏览</span><h2>本体发现</h2><p>查看业务定义、属性和资源之间的联系。这里展示类型定义；具体设备及其数值请到实例探索。</p></div><button @click="emit('navigate','explorer')">探索实例数据 →</button></header>
 <nav class="resource-tabs" aria-label="本体资源分类"><button v-for="c in categories" :key="c.id" :class="{active:category===c.id}" :aria-pressed="category===c.id" @click="selectCategory(c.id)"><strong>{{c.name}} <span>{{resources.filter(x=>x.kind===c.id).length}}</span></strong><small>{{c.en}}</small></button></nav>
 <div class="browse-toolbar"><label class="search-label"><span class="sr-only">搜索本体资源</span><input v-model="query" placeholder="搜索名称、别名、标识或定义" aria-label="搜索本体资源"></label><span>{{rows.length}} 项资源</span><div class="view-switch" aria-label="展示形式"><button :aria-pressed="view==='cards'" :class="{active:view==='cards'}" @click="view='cards'">卡片</button><button :aria-pressed="view==='list'" :class="{active:view==='list'}" @click="view='list'">列表</button></div></div>
 <div v-if="!rows.length" class="empty-resource"><h3>{{category==='groups'&&!query?'尚未定义对象类型组':'没有匹配的资源'}}</h3><p>{{category==='groups'&&!query?'对象类型组用于整理和查找对象类型，不代表设备的实际包含关系。当前模型没有组定义，因此不自动生成分组。':'可修改搜索条件，或前往对应的维护页面创建定义。'}}</p><button v-if="query" @click="query=''">清空搜索</button><button v-else-if="info.page" @click="emit('navigate',info.page)">前往维护</button></div>
 <div v-else class="browse-body">
  <div class="resource-list" :class="view"><button v-for="r in rows" :key="r.id" class="resource-item" :class="{selected:selected===r.id}" :aria-pressed="selected===r.id" @click="selected=r.id"><span class="resource-symbol">{{info.name.slice(0,1)}}</span><span class="resource-copy"><strong>{{r.name}}</strong><small>{{r.id}}</small><span class="resource-description">{{r.description||'尚未填写定义'}}</span></span><span class="selected-marker">{{selected===r.id?'已选':''}}</span></button></div>
  <aside v-if="current" class="resource-detail" :key="current.kind+current.id" aria-label="资源详情"><div class="detail-title"><span class="eyebrow">{{info.name}}</span><h3>{{current.name}}</h3><code>{{current.id}}</code></div><p class="definition">{{current.description||'尚未填写业务定义。'}}</p><div class="detail-actions"><button v-if="['objects','links'].includes(category)" @click="emit('graph',current.id)">在关系图查看</button><button v-if="category==='objects'" @click="emit('properties',current.id)">维护属性</button><button v-else-if="info.page" @click="emit('navigate',info.page)">前往维护</button></div>
   <template v-if="category==='objects'"><p v-if="current.raw['mg:aliases']?.length" class="muted">别名：{{current.raw['mg:aliases'].join('、')}}</p><h4>属性 <span>{{objectProperties.length}}</span></h4><div class="table-scroll"><table><thead><tr><th>名称</th><th>数据类型</th><th>来源</th></tr></thead><tbody><tr v-for="p in objectProperties" :key="idOf(p)"><td>{{title(resolveProperty(p))}}</td><td>{{dataType(p)}}</td><td><button v-if="p['mg:sharedProperty']" class="text-link" @click="openResource('shared',idOf(p['mg:sharedProperty']))">共享属性 ↗</button><span v-else>本地属性</span></td></tr></tbody></table></div><p v-if="!objectProperties.length" class="muted">尚未定义属性。</p><h4>相关链接 <span>{{relatedLinks.length}}</span></h4><button v-for="l in relatedLinks" :key="idOf(l)" class="related-row" @click="openResource('links',idOf(l))">{{name(idOf(l['rdfs:domain']))}} — {{title(l)}} → {{name(idOf(l['rdfs:range']))}}</button><p v-if="!relatedLinks.length" class="muted">暂无相关链接。</p><h4>关联行动 <span>{{relatedActions.length}}</span></h4><button v-for="a in relatedActions" :key="a.id" class="related-row" @click="openResource('actions',a.id)">{{a.name}} →</button><p v-if="!relatedActions.length" class="muted">暂无关联行动。</p></template>
   <template v-else-if="category==='links'"><dl><dt>起点对象类型</dt><dd><button class="text-link" @click="openResource('objects',idOf(current.raw['rdfs:domain']))">{{name(idOf(current.raw['rdfs:domain']))}}</button></dd><dt>终点对象类型</dt><dd><button class="text-link" @click="openResource('objects',idOf(current.raw['rdfs:range']))">{{name(idOf(current.raw['rdfs:range']))}}</button></dd><dt>数量关系</dt><dd>{{cardinality(current.raw)}}</dd><dt>反向名称</dt><dd>{{current.raw['mg:reverseLabel']||'未填写（选填）'}}</dd></dl></template>
   <template v-else-if="category==='shared'"><dl><dt>数据类型</dt><dd>{{dataType(current.raw)}}</dd><dt>单位／显示后缀</dt><dd>{{current.raw['mg:valueSuffix']||'未配置'}}</dd></dl><h4>使用位置 <span>{{sharedUsage.length}}</span></h4><button v-for="p in sharedUsage" :key="idOf(p)" class="related-row" @click="openResource('objects',idOf(p['rdfs:domain']))">{{name(idOf(p['rdfs:domain']))}} · {{title(p)}} →</button><p v-if="!sharedUsage.length" class="muted">尚未被对象属性引用。</p></template>
   <template v-else-if="category==='interfaces'"><p class="info-note">当前工作台展示已记录的属性契约和实现对象，不代表完整 Foundry 接口能力。</p><h4>属性契约</h4><button v-for="p in current.raw.properties||[]" :key="idOf(p)" class="related-row" @click="openResource('shared',idOf(p))">{{name(idOf(p))}} →</button><p v-if="!current.raw.properties?.length" class="muted">暂无属性契约。</p><h4>实现对象类型</h4><button v-for="t in current.raw.implementations||[]" :key="idOf(t)" class="related-row" @click="openResource('objects',idOf(reference(idOf(t)))||idOf(t))">{{name(idOf(t))}} →</button></template>
   <template v-else-if="category==='actions'"><p class="info-note">这里仅浏览行动定义；不会执行或下发设备指令。</p><dl><dt>作用对象</dt><dd>{{name(current.raw.object_type)}}</dd><dt>修改规则</dt><dd>{{current.raw.effect||'尚未填写'}}</dd><dt>提交条件</dt><dd>{{current.raw.criteria||'尚未填写'}}</dd><dt>验收要求</dt><dd>{{current.raw.acceptance||'尚未填写'}}</dd></dl><h4>输入参数</h4><div v-for="p in current.raw.inputs||[]" :key="p.name" class="parameter"><strong>{{p.name}}</strong> <span>{{p.type}} · {{p.required?'必填':'选填'}}</span><p>{{p.description||'尚未填写说明'}}</p></div></template>
   <template v-else-if="category==='groups'"><h4>组内对象类型</h4><button v-for="t in groupMembers" :key="idOf(t)" class="related-row" @click="openResource('objects',idOf(reference(idOf(t)))||idOf(t))">{{name(idOf(t))}} →</button><p v-if="!groupMembers.length" class="muted">该组未记录可识别的成员信息。</p></template>
   <details v-if="current.raw['mg:reviewNote']||current.raw.review_note"><summary>来源与核验说明</summary><p class="definition">{{current.raw['mg:reviewNote']||current.raw.review_note}}</p></details>
  </aside>
 </div>
</section>
</template>
<style scoped>
.discover{padding:24px;max-width:1600px;margin:auto;color:var(--ink)}.discover-heading{display:flex;justify-content:space-between;align-items:start;gap:20px}.discover-heading h2{margin:8px 0}.discover-heading p{color:var(--muted);line-height:1.7;margin-top:0}.resource-tabs{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px;margin:20px 0}.resource-tabs button{text-align:left;padding:14px 12px;background:var(--paper);border:1px solid var(--line);border-radius:var(--r-md)}.resource-tabs strong{display:block;font-size:14px}.resource-tabs small{display:block;color:var(--muted);font-size:12px;margin-top:7px}.resource-tabs strong span{float:right;color:var(--muted)}.resource-tabs button.active,.view-switch button.active{border-color:var(--blue-line);background:var(--blue-soft);color:var(--blue-ink)}.browse-toolbar{display:flex;gap:16px;align-items:center;margin-bottom:16px;color:var(--muted);font-size:13px}.search-label{flex:1;max-width:480px}.search-label input{width:100%;box-sizing:border-box;padding:11px 13px;border:1px solid var(--line-2);border-radius:var(--r-sm);background:var(--paper)}.view-switch{display:flex;margin-left:auto;gap:4px}.browse-body{display:grid;grid-template-columns:minmax(320px,1fr) minmax(380px,1.1fr);gap:18px;align-items:start}.resource-list{display:grid;gap:10px;align-content:start}.resource-list.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.resource-item{text-align:left;border:1px solid var(--line);border-radius:var(--r-md);background:var(--paper);padding:16px;display:flex;gap:10px;align-items:start;min-width:0;color:inherit}.resource-item.selected{border-color:var(--blue);box-shadow:0 0 0 1px var(--blue);background:var(--blue-soft)}.resource-symbol{flex-shrink:0;background:var(--blue-soft);color:var(--blue-ink);border-radius:var(--r-sm);padding:8px;font-size:13px}.resource-copy{display:flex;flex-direction:column;gap:7px;min-width:0;flex:1}.resource-copy strong{font-size:15px}.resource-copy small{font-size:12px;overflow-wrap:anywhere;color:var(--muted)}.resource-description{font-size:12px;line-height:1.7;color:var(--muted);display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.selected-marker{font-size:12px;color:var(--blue-ink);white-space:nowrap}.cards .resource-item{flex-wrap:wrap}.cards .resource-symbol{display:none}.resource-detail{background:var(--paper);border:1px solid var(--line);border-radius:var(--r-md);padding:24px;min-width:0}.detail-title h3{font-size:23px;margin:8px 0}.detail-title code{font-size:12px;color:var(--muted);overflow-wrap:anywhere}.definition{white-space:pre-wrap;font-size:13px;line-height:1.85}.detail-actions{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.resource-detail h4{border-top:1px solid var(--paper-3);padding-top:20px;margin-bottom:12px;font-size:14px}.resource-detail h4 span{color:var(--muted);margin-left:5px}.table-scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:12px}th,td{text-align:left;padding:10px 8px;border-bottom:1px solid var(--paper-3)}th{background:var(--bg);color:var(--muted);font-weight:500}.text-link{border:0;background:none;color:var(--blue-ink);padding:0;font-size:inherit;cursor:pointer}.related-row{display:block;text-align:left;width:100%;background:var(--paper-2);border:1px solid var(--paper-3);border-radius:var(--r-sm);padding:11px;margin-bottom:7px;font-size:12px;color:var(--muted);line-height:1.6}.muted{color:var(--faint);font-size:12px}.info-note{background:var(--blue-soft);color:var(--ink-2);padding:12px;border-radius:var(--r-sm);font-size:12px;line-height:1.8}dl{font-size:13px}dt{color:var(--muted);margin:18px 0 6px}dd{margin:0;white-space:pre-wrap;line-height:1.8}.parameter{border-bottom:1px solid var(--paper-3);padding:12px 0;font-size:12px}.parameter span{color:var(--muted)}.parameter p{margin-bottom:0;line-height:1.7}.empty-resource{background:var(--paper);border:1px dashed var(--line-2);border-radius:var(--r-md);padding:50px 24px;text-align:center}.empty-resource p{color:var(--muted);font-size:13px;line-height:1.8}details{margin-top:20px;font-size:12px;color:var(--muted)}summary{cursor:pointer}@media(max-width:1100px){.resource-tabs{grid-template-columns:repeat(3,1fr)}.resource-list.cards{grid-template-columns:1fr}}@media(max-width:760px){.discover{padding:14px}.browse-body{grid-template-columns:1fr}.discover-heading{flex-direction:column}.resource-tabs{grid-template-columns:repeat(2,1fr)}.browse-toolbar{flex-wrap:wrap}.resource-detail{padding:18px}}
</style>
